# ================= LOAD SUDO USERS =================
SUDO_FILE = "sudo_users.json"

def load_sudo():
    global SUDO_USERS
    try:
        if os.path.exists(SUDO_FILE):
            with open(SUDO_FILE, "r") as f:
                data = json.load(f)
                SUDO_USERS = set(data.get("users", []))
    except:
        SUDO_USERS = set()

def save_sudo():
    try:
        with open(SUDO_FILE, "w") as f:
            json.dump({"users": list(SUDO_USERS)}, f)
    except:
        pass

load_sudo()

# ================= AUTHORIZATION DECORATOR =================
def only_sudo(func):
    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE):
        if not update.effective_user:
            return
        uid = update.effective_user.id
        if uid != OWNER_ID and uid not in SUDO_USERS:
            try:
                await update.message.reply_text(AUTHORIZATION_MSG)
            except:
                pass
            return
        return await func(update, context)
    return wrapper

def only_owner(func):
    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE):
        if not update.effective_user:
            return
        uid = update.effective_user.id
        if uid != OWNER_ID:
            try:
                await update.message.reply_text("🚫 Only owner can use this command!")
            except:
                pass
            return
        return await func(update, context)
    return wrapper

# ================= SET PREFIX COMMAND =================
@only_owner
async def setprefix_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global CURRENT_PREFIX
    if not context.args:
        await update.message.reply_text(f"Current prefix: `{CURRENT_PREFIX}`\nUsage: .setprefix <new_prefix>", parse_mode="Markdown")
        return
    new_prefix = context.args[0].strip()
    if len(new_prefix) > 3:
        await update.message.reply_text("❌ Prefix too long! Max 3 characters.")
        return
    CURRENT_PREFIX = new_prefix
    await update.message.reply_text(f"✅ Prefix changed to: `{CURRENT_PREFIX}`", parse_mode="Markdown")

