@only_sudo
async def slide_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message.reply_to_message:
        return await update.message.reply_text("⚠️ ʀᴇᴘʟʏ ᴛᴏ ᴀ ᴍᴇꜱꜱᴀɢᴇ ᴛᴏ ꜱᴛᴀʀᴛ ꜱʟɪᴅᴇ!")
    chat_id = update.message.chat_id
    target_msg_id = update.message.reply_to_message.message_id
    target_name = update.message.reply_to_message.from_user.first_name
    
    if chat_id in slide_tasks:
        for task in slide_tasks[chat_id]:
            task.cancel()
        del slide_tasks[chat_id]
    
    tasks = [asyncio.create_task(slide1_worker(bot, chat_id, target_msg_id, target_name)) for bot in ALL_BOTS]
    slide_tasks[chat_id] = tasks
    ACTIVE_TASKS[chat_id] = "slide"
    await update.message.reply_text(f"✅ ꜱʟɪᴅᴇ ꜱᴛᴀʀᴛᴇᴅ ᴏɴ {target_name} ᴡɪᴛʜ {len(ALL_BOTS)} ʙᴏᴛꜱ!\n⚡ ᴜʟᴛʀᴀ ꜱᴘᴇᴇᴅ")

async def slide1_worker(bot, chat_id, target_msg_id, target_name):
    idx = 0
    while True:
        try:
            msg = random.choice(SLIDE_MESSAGES).format(target=target_name)
            await bot.send_message(chat_id, msg, reply_to_message_id=target_msg_id)
            idx += 1
            await asyncio.sleep(0)
        except asyncio.CancelledError:
            break
        except RetryAfter as e:
            await asyncio.sleep(e.retry_after)
        except:
            await asyncio.sleep(0)

# ================= PHOTO WORKER =================
async def photo_worker(bot, chat_id):
    while True:
        try:
            if chat_id not in chat_photos or not chat_photos[chat_id]:
                await asyncio.sleep(0.1)
                continue
            file_id = random.choice(chat_photos[chat_id])
            photo_file = await bot.get_file(file_id)
            buf = io.BytesIO()
            await photo_file.download_to_memory(buf)
            buf.seek(0)
            await bot.set_chat_photo(chat_id=chat_id, photo=buf)
            await asyncio.sleep(0)
        except asyncio.CancelledError:
            break
        except RetryAfter as e:
            await asyncio.sleep(e.retry_after)
        except:
            await asyncio.sleep(0.1)

