# ================= PHOTO COMMANDS =================
@only_sudo
async def savephoto_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message.reply_to_message or not update.message.reply_to_message.photo:
        return await update.message.reply_text("⚠️ ʀᴇᴘʟʏ ᴛᴏ ᴀ ᴘʜᴏᴛᴏ ᴛᴏ ꜱᴀᴠᴇ ɪᴛ!")
    chat_id = update.message.chat_id
    file_id = update.message.reply_to_message.photo[-1].file_id
    chat_photos.setdefault(chat_id, []).append(file_id)
    await update.message.reply_text(f"✅ ᴘʜᴏᴛᴏ ꜱᴀᴠᴇᴅ! ᴛᴏᴛᴀʟ: {len(chat_photos[chat_id])}")

@only_sudo
async def startphoto_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.message.chat_id
    if chat_id not in chat_photos or len(chat_photos[chat_id]) < 1:
        return await update.message.reply_text("⚠️ ꜱᴀᴠᴇ ᴀᴛʟᴇᴀꜱᴛ ᴏɴᴇ ᴘʜᴏᴛᴏ ᴜꜱɪɴɢ (ᴘʀᴇꜰɪx)ꜱᴀᴠᴇᴘʜᴏᴛᴏ")
    if chat_id in photo_tasks:
        for task in photo_tasks[chat_id]:
            task.cancel()
        del photo_tasks[chat_id]
    
    tasks = [asyncio.create_task(photo_worker(bot, chat_id)) for bot in ALL_BOTS]
    photo_tasks[chat_id] = tasks
    ACTIVE_TASKS[chat_id] = "ᴘʜᴏᴛᴏ"
    await update.message.reply_text(f"✅ ᴘʜᴏᴛᴏ ʟᴏᴏᴘ ꜱᴛᴀʀᴛᴇᴅ ᴡɪᴛʜ {len(ALL_BOTS)} ʙᴏᴛꜱ!\nᴘʜᴏᴛᴏꜱ: {len(chat_photos[chat_id])}\n⚡ ᴜʟᴛʀᴀ ꜱᴘᴇᴇᴅ")

@only_sudo
async def clearphotos_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.message.chat_id
    if chat_id in chat_photos:
        del chat_photos[chat_id]
        await update.message.reply_text("🗑️ ꜱᴀᴠᴇᴅ ᴘʜᴏᴛᴏ ᴄʟᴇᴀʀᴇᴅ!")
    else:
        await update.message.reply_text("❌ ꜱᴀᴠᴇ ᴀɴʏ ᴘʜᴏᴛᴏ")

