@only_sudo
async def stopall_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.message.chat_id
    for d in (nc_tasks, spam_tasks, slide_tasks, photo_tasks):
        if chat_id in d:
            for task in d[chat_id]:
                task.cancel()
            del d[chat_id]
    if chat_id in ACTIVE_TASKS:
        del ACTIVE_TASKS[chat_id]
    await update.message.reply_text("🛑 ᴀʟʟ ᴛᴀꜱᴋꜱ ꜱᴛᴏᴘᴘᴇᴅ!")

# ================= SUDO MANAGEMENT COMMANDS =================
@only_owner
async def addsudo_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message.reply_to_message:
        return await update.message.reply_text("❌ ᴊɪꜱᴋᴏ ɢᴜʟᴀᴀᴍ ʙᴀɴᴀ ɴᴀ ʜᴀɪ ᴜꜱᴋᴏ ʀᴇᴘʟʏ ᴋᴀʀᴏᴏ!")
    uid = update.message.reply_to_message.from_user.id
    SUDO_USERS.add(uid)
    save_sudo()
    await update.message.reply_text(f"✅ ɢᴜʟᴀᴀᴍ ʙᴀɴ ɢᴀʏᴀ: {uid}")

@only_owner
async def delsudo_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message.reply_to_message:
        return await update.message.reply_text("❌ ᴊɪꜱᴋᴏ ꜱᴇ ɢᴜʟᴀᴀᴍ ꜱᴇ ʜᴀᴛᴀ ɴᴀ ʜᴀɪ ᴜꜱᴋᴏ ʀᴇᴘʟʏ ᴋᴀʀᴏ!")
    uid = update.message.reply_to_message.from_user.id
    if uid == OWNER_ID:
        return await update.message.reply_text("❌ ᴄᴀɴɴᴏᴛ ʀᴇᴍᴏᴠᴇ ᴏᴡɴᴇʀ!")
    if uid in SUDO_USERS:
        SUDO_USERS.remove(uid)
        save_sudo()
        await update.message.reply_text(f"✅ ᴍᴀᴀ ᴄʜᴜᴅᴀ ʀɴᴅʏᴋᴇ: {uid}")
    else:
        await update.message.reply_text("❌ ʏᴇ ɢᴜʟᴀᴀᴍ ɴɪ ʜᴀɪ!")

@only_sudo
async def listsudo_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    lines = ["👑 SUDO USERS LIST:"]
    for uid in SUDO_USERS:
        if uid == OWNER_ID:
            lines.append(f"👑 {uid} (Owner)")
        else:
            lines.append(f"🛡️ {uid}")
    lines.append(f"\nTotal: {len(SUDO_USERS)}")
    await update.message.reply_text("\n".join(lines))

