@only_sudo
async def status_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uptime = int(time.time() - start_time)
    hours = uptime // 3600
    minutes = (uptime % 3600) // 60
    seconds = uptime % 60
    
    status_text = f"""
𓆩🌐𓆪 ⪻ 𝐁ꪮᴛ ꫝᴄᴛɪꪜɪᴛʏ ⪼
𓆩⏱️𓆪 **Ⴎᴘᴛɪᴍᴇ:** {hours}h {minutes}m {seconds}s
𓆩⚡𓆪 **Տᴘᴇᴇᴅ:** 0.0s (ULTRA FAST)
𓆩🤖𓆪 **Ᏼᴏᴛꜱ ϴɴʟɪɴᴇ:** {len(ALL_BOTS)}
𓆩🔄𓆪 **Νᴄ Ͳᴀꜱᴋꜱ:** {len(nc_tasks)}
𓆩💬𓆪 **Տᴘᴀᴍ Ͳᴀꜱᴋꜱ:** {len(spam_tasks)}
𓆩🎯𓆪 **Տʟɪᴅᴇ Ͳᴀꜱᴋꜱ:** {len(slide_tasks)}
𓆩📸𓆪 **Ꮲʜᴏᴛᴏ Ͳᴀꜱᴋꜱ:** {len(photo_tasks)}
𓆩👑𓆪 **Տᴜᴅᴏ Ⴎꜱᴇʀꜱ:** {len(SUDO_USERS)}
𓆩🔥𓆪 **Ғʟᴏᴏᴅʟᴇꜱꜱ:** ACTIVE
𓆩👑𓆪 **Ꮲᴏᴡᴇʀᴅ Ᏼʏ:**@kwo9x
𓍼ֶָ֢˖Rexxy ָ🎀་༘
"""
    await update.message.reply_text(status_text, parse_mode="Markdown")

@only_sudo
async def ping_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    start = time.time()
    msg = await update.message.reply_text("🏓 Pinging...")
    end = time.time()
    await msg.edit_text(f"🏓 ᴘᴏɴɢ! {round((end - start) * 1000)}ms")

# ================= PROMOTE ALL BOTS =================
@only_sudo
async def promoteallbots_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.message.chat_id
    
    try:
        bot_member = await context.bot.get_chat_member(chat_id, context.bot.id)
        if bot_member.status not in ['administrator', 'creator']:
            return await update.message.reply_text("❌ ɪ ɴᴇᴇᴅ ᴛᴏ ʙᴇ ᴀᴅᴍɪɴ ꜰɪʀꜱᴛ!")
    except:
        return await update.message.reply_text("❌ ꜰᴀɪᴇʟᴅ ᴛᴏ ᴄʜᴇᴄᴋ ᴀᴅᴍɪɴ ꜱᴛᴀᴛᴜꜱ!")
    
    status_msg = await update.message.reply_text("🔄 ᴘʀᴏᴍᴏᴛɪɴɢ ʙᴏᴛꜱ...")
    promoted = 0
    failed = 0
    
    for bot in ALL_BOTS:
        try:
            me = await bot.get_me()
            await context.bot.promote_chat_member(
                chat_id=chat_id,
                user_id=me.id,
                can_change_info=True,
                can_delete_messages=True,
                can_invite_users=True,
                can_restrict_members=True,
                can_pin_messages=True,
                can_promote_members=True,
                can_manage_chat=True,
                can_manage_video_chats=True
            )
            promoted += 1
            await status_msg.edit_text(f"🔄 ᴘʀᴏᴍᴏᴛᴇᴅ {promoted} ʙᴏᴛꜱ...")
        except:
            failed += 1
            continue
    
    await status_msg.edit_text(
        f"✅  ᴘʀᴏᴍᴏᴛɪᴏɴ ᴄᴏᴍᴘʟᴇᴛᴇ!\n"
        f"📊 ᴘʀᴏᴍᴏᴛᴇᴅ: {promoted} bots\n"
        f"❌ ꜰᴀɪʟᴇᴅ: {failed} bots"
    )

# ================= LEAVE COMMAND =================
@only_sudo
async def leave_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.message.chat_id
    chat_title = update.effective_chat.title or "this chat"
    await update.message.reply_text(f"👋 ʟᴇᴀᴠɪɴɢ {chat_title}...")
    for bot in ALL_BOTS:
        try:
            await bot.leave_chat(chat_id)
        except:
            pass

# ================= DELAY COMMAND =================
@only_sudo
async def delay_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global GLOBAL_DELAY
    if not context.args:
        await update.message.reply_text(f"Current delay: {GLOBAL_DELAY}s\nUsage: .delay <seconds>")
        return
    try:
        new_delay = float(context.args[0])
        if new_delay < 0.0:
            new_delay = 0.0
        if new_delay > 5.0:
            new_delay = 5.0
        GLOBAL_DELAY = new_delay
        await update.message.reply_text(f"✅ ᴅᴇʟᴀʏ ꜱᴇᴛ ᴛᴏ {GLOBAL_DELAY}s")
    except:
        await update.message.reply_text("❌ ɴᴜᴍʙᴇʀ ꜱᴀʜɪ ɴɪ ʜᴀɪ!")

